"use client";
/**
 * EosConnectLink: two tiles joined by three dots, read as "Connect A and B". A light travels along the dots from the
 * first app to the second, in a calm loop with a rest between passes. The loop runs on the compositor (transform and
 * opacity) and only while the link is on screen in a visible tab; with reduced motion the dots hold still.
 */
import { useRef, type CSSProperties, type ReactNode } from "react";
import { EosSunGlyph, type EosAppKind } from "./glyphs";
import { EOS_TILE_SIZES, EosIconTile, type EosIconTileSize, type EosIconTileTone } from "./icon-tile";
import { useEosLoop } from "./motion";
import { cx } from "./shared";
import { EosScope } from "./theme";

export interface EosConnectEnd {
  /** The app's name, used in the accessible name. */
  label: string;
  app?: EosAppKind;
  /** Your own glyph instead of an app's. */
  icon?: ReactNode;
}

const CSS = `
.eos-connect{display:inline-flex;align-items:center;gap:var(--eos-connect-gap)}
.eos-connect-dots{display:inline-flex;align-items:center;gap:var(--eos-connect-dot-gap)}
.eos-connect-dot{position:relative;display:block;width:var(--eos-connect-dot);height:var(--eos-connect-dot);border-radius:50%;box-sizing:border-box;border:1.5px solid var(--eos-frost-rim);background:var(--eos-frost);box-shadow:inset 0 1px 0 var(--eos-frost-highlight);--eos-connect-light:var(--eos-frost-highlight)}
.eos-connect-dot::after{content:"";position:absolute;inset:-1.5px;border-radius:50%;background:var(--eos-connect-light);opacity:0}
.eos-connect[data-tone=white] .eos-connect-dot{border-color:var(--eos-hairline-strong);background:var(--eos-tile);--eos-connect-light:var(--eos-text-tertiary)}
.eos-connect[data-pulse=true] .eos-connect-dot,.eos-connect[data-pulse=true] .eos-connect-dot::after{animation:eos-connect-travel var(--eos-dots) cubic-bezier(.45,0,.55,1) infinite both;animation-delay:calc(var(--eos-dot-i) * var(--eos-dots) * .14);animation-play-state:paused}
.eos-connect[data-pulse=true] .eos-connect-dot::after{animation-name:eos-connect-light}
.eos-connect[data-pulse=true][data-eos-loop=on] .eos-connect-dot,.eos-connect[data-pulse=true][data-eos-loop=on] .eos-connect-dot::after{animation-play-state:running}
@keyframes eos-connect-travel{0%,46%,100%{transform:scale(1)}18%{transform:scale(1.22)}}
@keyframes eos-connect-light{0%,46%,100%{opacity:0}18%{opacity:.92}}
@media (prefers-reduced-motion:reduce){.eos-connect[data-pulse=true] .eos-connect-dot,.eos-connect[data-pulse=true] .eos-connect-dot::after{animation:none}}
`;

export interface EosConnectLinkProps {
  from?: EosConnectEnd;
  to?: EosConnectEnd;
  tone?: EosIconTileTone;
  size?: EosIconTileSize;
  /** Send the light along the dots, in a loop that runs only while the link shows. */
  pulse?: boolean;
  className?: string;
  style?: CSSProperties;
}

const MORROW: EosConnectEnd = { label: "Morrow" };
const COFFER: EosConnectEnd = { label: "Coffer", app: "books" };

export function EosConnectLink({ from = MORROW, to = COFFER, tone = "frosted", size = "lg", pulse = true, className, style }: EosConnectLinkProps) {
  const link = useRef<HTMLDivElement>(null);
  useEosLoop(link, pulse);
  const side = EOS_TILE_SIZES[size].side;
  const dot = Math.max(7, Math.round(side * 0.15));
  const vars = {
    "--eos-connect-dot": `${dot}px`,
    "--eos-connect-dot-gap": `${Math.round(dot * 0.7)}px`,
    "--eos-connect-gap": `${Math.round(side * 0.2)}px`,
  } as CSSProperties;
  const end = (e: EosConnectEnd) => {
    const glyph = Math.round(side * 0.5);
    const icon = e.icon ?? (e.app ? undefined : <EosSunGlyph size={glyph} />);
    return <EosIconTile app={e.app} icon={icon} tone={tone} size={size} />;
  };
  return (
    <EosScope>
      <style>{CSS}</style>
      <div
        ref={link}
        className={cx("eos-connect", className)}
        role="img"
        aria-label={`Connect ${from.label} and ${to.label}`}
        data-tone={tone}
        data-pulse={pulse}
        style={{ ...vars, ...style }}
      >
        {end(from)}
        <span className="eos-connect-dots" aria-hidden>
          {[0, 1, 2].map((i) => (
            <span key={i} className="eos-connect-dot" style={{ "--eos-dot-i": i } as CSSProperties} />
          ))}
        </span>
        {end(to)}
      </div>
    </EosScope>
  );
}

// @zeus-internal
/** Small helpers the Eos pieces share. */
import { useCallback, useEffect, useLayoutEffect, useState } from "react";

export const cx = (...parts: (string | false | null | undefined)[]) => parts.filter(Boolean).join(" ");

export const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** A value that is controlled when `value` is given and owned here otherwise. */
export function useControlled<T>(value: T | undefined, initial: T, onChange?: (next: T) => void) {
  const [own, setOwn] = useState(initial);
  const current = value === undefined ? own : value;
  const set = useCallback(
    (next: T) => {
      if (value === undefined) setOwn(next);
      onChange?.(next);
    },
    [value, onChange],
  );
  return [current, set] as const;
}

/**
 * Whether a media query matches. The server and the first render use `initial`, so markup hydrates; the real answer
 * follows once mounted, and changes as the window does.
 */
export function useMedia(query: string, initial = false): boolean {
  const [matches, setMatches] = useState(initial);
  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const list = window.matchMedia(query);
    const update = () => setMatches(list.matches);
    update();
    list.addEventListener?.("change", update);
    return () => list.removeEventListener?.("change", update);
  }, [query]);
  return matches;
}

/** The index a roving-focus key moves to, or -1 for a key the group ignores. */
export function rovingIndex(key: string, index: number, count: number): number {
  if (count === 0) return -1;
  if (key === "ArrowRight" || key === "ArrowDown") return (index + 1) % count;
  if (key === "ArrowLeft" || key === "ArrowUp") return (index - 1 + count) % count;
  if (key === "Home") return 0;
  if (key === "End") return count - 1;
  return -1;
}

/** Visually hidden text for assistive technology. */
export const SR_ONLY_CSS =
  ".eos-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}";
